const express = require('express');
const metascraper = require('metascraper')([require('metascraper-image')()]);

const app = express();
app.use(express.json());

app.post('/bookmark', async (req, res) => {
  const html = await (await fetch(req.body.url)).text();
  const meta = await metascraper({html, url: req.body.url});
  const img = await fetch(meta.image);
  res.send(Buffer.from(await img.arrayBuffer()));
});

import {Hono} from 'hono';
