const fs = require('fs');
const path = require('path');
const yauzl = require('yauzl');

function extract(zipPath, target) {
  yauzl.open(zipPath, {lazyEntries: true}, (err, zipfile) => {
    zipfile.on('entry', (entry) => {
      const safe = entry.fileName.replace(/^\/+/, '');
      const dest = path.join(target, safe);
      zipfile.openReadStream(entry, (err, stream) => {
        stream.pipe(fs.createWriteStream(dest));
        zipfile.readEntry();
      });
    });
    zipfile.readEntry();
  });
}

const Fastify = require('fastify');

const app = Fastify();

app.get('/redirect', async (request, reply) => {
  const {code} = request.query;
  return reply
    .type('text/html')
    .send(`<script>if (window.opener) window.opener.postMessage({code: ${JSON.stringify(code)}}, '*')</script>`);
});

app.listen({port: 3000});

